def apply(path, edits, revert):
    with io.open(path, "r", encoding="utf-8", newline="") as f:
        text = f.read()

    ok = 0
    for old, new in edits:
        a, b = (new, old) if revert else (old, new)
        n = text.count(a)
        if n != 1:
            print("  !! anchor found %d times (expected 1): %r" % (n, a[:70]))
            continue
        text = text.replace(a, b, 1)
        ok += 1

    if not revert:
        with io.open(path, "w", encoding="utf-8", newline="") as f:
            f.write(text)
    else:
        with io.open(path, "w", encoding="utf-8", newline="") as f:
            f.write(text)

    print("  %s: %d/%d edits applied" % (os.path.basename(path), ok, len(edits)))
    return ok == len(edits)


if __name__ == "__main__":
