def process(path, edits, mode, lines):
    with open(path, "rb") as f:
        data = f.read()

    original = data
    counts = {"applied": 0, "already": 0, "missing": 0}

    for old, new in edits:
        a, b = (new, old) if mode == "revert" else (old, new)

        if data.count(a) == 0 and data.count(b) > 0:
            counts["already"] += 1
            continue

        n = data.count(a)
        if n != 1:
            counts["missing"] += 1
            lines.append("   MISSING (found %d): %r" % (n, a[:60]))
            continue

        data = data.replace(a, b, 1)
        counts["applied"] += 1

    changed = data != original
    if counts["missing"] == 0 and changed:
        with open(path, "wb") as f:
            f.write(data)

    lines.append("  %-24s applied=%d already=%d missing=%d written=%s"
                 % (os.path.basename(path), counts["applied"],
                    counts["already"], counts["missing"], "yes" if (changed and counts["missing"] == 0) else "no"))
    return counts["missing"] == 0


def main():
    args = sys.argv[1:]
    if "--revert" in args:
        mode = "revert"
    elif "--status" in args:
        mode = "status"
    else:
        mode = "apply"

    lines = ["USBDBG patch -- mode=%s" % mode]

    if mode == "status":
        for path, edits in ((DEV, EDITS_DEV), (AP, EDITS_AP)):
            with open(path, "rb") as f:
                data = f.read()
            done = sum(1 for o, n in edits if data.count(n) > 0)
            lines.append("  %-24s patched %d/%d" % (os.path.basename(path), done, len(edits)))
        ok = True
    else:
        ok = process(DEV, EDITS_DEV, mode, lines)
        ok = process(AP, EDITS_AP, mode, lines) and ok

    with open(REPORT, "w", encoding="utf-8", newline="") as f:
        f.write("\n".join(lines) + "\n")

    print("\n".join(lines))
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

