import re
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
PROJ = os.path.dirname(ROOT)
TARGET = os.path.join(PROJ, "vendor", "sifli", "chips", "sf32lb52",
                      "sf32lb_usbdev.c")
