def crlf(text):
    return text.replace("\n", "\r\n").encode("utf-8")


def apply():
    data = read(TARGET)
    nl = b"\r\n" if b"\r\n" in data else b"\n"
    print("[文件] %s" % TARGET)
    print("[换行] %s" % ("CRLF" if nl == b"\r\n" else "LF"))

    if MARKER in data:
        print("[跳过] 补丁已应用过（检测到 ep0setupout）")
        return 0

    # 先整体校验，全部匹配才动手
    plan = []
    for name, old, new in EDITS:
        ob = crlf(old) if nl == b"\r\n" else old.encode("utf-8")
