    if not os.path.exists(BACKUP):
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copy2(TARGET, BACKUP)
        print("[备份] -> %s" % BACKUP)

    for name, ob, nb in plan:
        data = data.replace(ob, nb, 1)
        print("[应用] %s" % name)

    write(TARGET, data)

    # 校验
    data = read(TARGET)
    checks = [
        ("ep0setupout 字段", data.count(b"ep0setupout"), 5),
        ("ep0data 缓冲", data.count(b"ep0data["), 3),
        ("dataout 参数", data.count(b"uint8_t *dataout"), 2),
        ("CLASS_SETUP 传数据", data.count(b"ctrl, dataout, outlen"), 1),
        ("NULL,0 直接派发调用", data.count(b"sf32lb52_dispatchrequest(priv, &ctrl, NULL, 0)"), 1),
        ("派发调用总数", data.count(b"sf32lb52_dispatchrequest(priv,"), 3),
    ]
    bad = 0
    for name, got, want in checks:
        ok = "ok" if got == want else "**不符合**"
        if got != want:
            bad += 1
        print("  [%s] %s = %d (期望 %d)" % (ok, name, got, want))

    print("[完成] 补丁应用%s" % ("成功" if bad == 0 else "但有校验异常"))
    return 0 if bad == 0 else 3


def revert():
    if not os.path.exists(BACKUP):
        print("[错误] 没有备份文件 %s" % BACKUP)
        return 2
    shutil.copy2(BACKUP, TARGET)
    data = read(TARGET)
    print("[回退] 已从备份恢复，ep0setupout 存在 = %s" % (MARKER in data))
    return 0


def status():
    data = read(TARGET)
    print("[状态] %s" % ("已应用" if MARKER in data else "未应用"))
    print("       大小 %d 字节, CR=%d LF=%d" %
          (len(data), data.count(b"\r"), data.count(b"\n")))
    print("       ep0setupout=%d  dataout=%d" %
          (data.count(b"ep0setupout"), data.count(b"uint8_t *dataout")))
    return 0


if __name__ == "__main__":
    if len(sys.argv) > 1:
        if sys.argv[1] == "--revert":
            sys.exit(revert())
        if sys.argv[1] == "--status":
            sys.exit(status())
    sys.exit(apply())

