```c
// SDK bf0_hal_pcd.c:1247-1264  —— 遇到 SETUPEND 时会重新检查并「处理」挂起的 SETUP
if (csr & USB_CSR0_P_SETUPEND) { ep0->csr0 = USB_CSR0_P_SETUPEND; ... csr = ep0->csr0; }
switch (hpcd->ep0_state) {
case HAL_PCD_EP0_ACKWAIT:
    if (csr & USB_CSR0_RXPKTRDY) goto setup;   ← 关键：转去处理，不丢包
```

