#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_ep0setupend.py -- stop dropping SETUPs that arrive with SETUPEND set.

Symptom this fixes
------------------
After SET_CONFIGURATION the host sent SEND_ENCAPSULATED_COMMAND (the RNDIS
REMOTE_NDIS_INITIALIZE_MSG) and the board console showed *nothing* -- no
`USBDBG setup:` line at all, then the transfer timed out and Windows reported
code 10 (CM_PROB_FAILED_START) with problem status 0xC0000000/1.

Root cause
----------
When a SETUP packet arrives before the previous control transfer has finished,
the MUSB controller sets SETUPEND *and* RXPKTRDY together.  The EP0 interrupt
handler used a plain `else if` chain:

    else if (csr0 & USB_CSR0_P_SETUPEND)
      {
        hw->csr0_txcsr = USB_CSR0_P_SVDSETUPEND;   /* and return */
      }
    else if (csr0 & USB_CSR0_RXPKTRDY)
      {
        sf32lb52_ep0setup(priv);                   /* never reached */
      }

so the SETUPEND branch won and the pending SETUP was never parsed: the payload
stayed in the FIFO, RXPKTRDY was never cleared (no further interrupt), and the
host never got a reply.

The SiFli SDK HAL does it the other way round (PCD_EP0_ISR_Handler):

    if (csr & USB_CSR0_P_SETUPEND) { ep0->csr0 = USB_CSR0_P_SETUPEND; ... }
    switch (hpcd->ep0_state)
      {
      case HAL_PCD_EP0_ACKWAIT:
        if (csr & USB_CSR0_RXPKTRDY) goto setup;   /* process it */

i.e. it clears SETUPEND and then still handles the pending SETUP.

Clearing SETUPEND via SVDSETUPEND does not consume the packet: RXPKTRDY is a
hardware status bit that is only cleared by COUNT0 or SVDRXPKTRDY.

Usage:
  python patch_ep0setupend.py            apply
  python patch_ep0setupend.py --revert   restore backup
  python patch_ep0setupend.py --status   report
"""

import os
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "vendor", "sifli", "chips", "sf32lb52",
                   "sf32lb_usbdev.c")
BAK = os.path.join(ROOT, ".workbuddy", "backup",
                   "sf32lb_usbdev.c.pre_setupend")
MARKER = "USBDBG: SETUPEND cleared"

OLD = '''      else if (csr0 & USB_CSR0_P_SETUPEND)
        {
          usbtrace(TRACE_INTENTRY(SF32LB52_TRACEINTID_TXFIFOSETEND),
                   csr0);

          /* Clear SetupEnd */

          hw->csr0_txcsr = USB_CSR0_P_SVDSETUPEND;
        }
'''

NEW = '''      else if (csr0 & USB_CSR0_P_SETUPEND)
        {
          usbtrace(TRACE_INTENTRY(SF32LB52_TRACEINTID_TXFIFOSETEND),
                   csr0);

          /* A SETUP that arrives before the previous control transfer has
           * finished sets SETUPEND *and* RXPKTRDY.  Clearing SETUPEND does
           * not consume the packet -- RXPKTRDY is a hardware status bit that
           * only COUNT0 or SVDRXPKTRDY clears -- so the pending SETUP still
           * has to be parsed here.  Bailing out at this point (as this code
           * used to) silently swallowed the host's request: the packet stayed
           * in the FIFO, RXPKTRDY was never cleared so no further interrupt
           * arrived, and the host waited for a reply that never came.
           *
           * The SDK HAL does exactly this in PCD_EP0_ISR_Handler(): it clears
           * SETUPEND and then re-reads CSR0, jumping to the setup handler when
           * RXPKTRDY is still set.
           *
           * Any half-received OUT data stage is abandoned -- the new SETUP
           * supersedes it.
           */

          hw->csr0_txcsr = USB_CSR0_P_SVDSETUPEND;

          priv->ep0setupout = 0;
          priv->ep0datlen   = 0;
          priv->ep0outlen   = 0;

          hw->index = 0;
          csr0 = hw->csr0_txcsr;

#if USBDBG
          _err("USBDBG: SETUPEND cleared, csr0 now=%04x\\n",
               (unsigned)csr0);
#endif

          if (csr0 & USB_CSR0_RXPKTRDY)
            {
              sf32lb52_ep0setup(priv);
            }
        }
'''

# Also flag a status stage that is stuck waiting for TXPKTRDY to clear: that
# would mean the host never came back for the final packet.
E2_OLD = '''  if (hw->csr0_txcsr & USB_CSR0_TXPKTRDY)
    {
      return -EAGAIN;
    }
'''

E2_NEW = '''  if (hw->csr0_txcsr & USB_CSR0_TXPKTRDY)
    {
#if USBDBG
      _err("USBDBG: ep0write busy (TXPKTRDY), nbytes=%u last=%d -- retry\\n",
           (unsigned)nbytes, (int)last);
#endif
      return -EAGAIN;
    }
'''


def read_text():
    with open(SRC, "rb") as fh:
        raw = fh.read()
    crlf = b"\r\n" in raw
    return raw.replace(b"\r\n", b"\n").decode("utf-8"), crlf


def write_text(text, crlf):
    data = text.encode("utf-8")
    if crlf:
        data = data.replace(b"\n", b"\r\n")
    with open(SRC, "wb") as fh:
        fh.write(data)


def apply():
    text, crlf = read_text()
    if MARKER in text:
        print("already applied -- nothing to do")
        return 0

    if text.count(OLD) != 1:
        print("FAIL: SETUPEND anchor matched %d times" % text.count(OLD))
        return 1
    text = text.replace(OLD, NEW)
    print("edit1 ok: SETUPEND branch now processes the pending SETUP")

    if text.count(E2_OLD) != 1:
        print("FAIL: ep0write anchor matched %d times" % text.count(E2_OLD))
        return 1
    text = text.replace(E2_OLD, E2_NEW)
    print("edit2 ok: ep0write logs a stuck TXPKTRDY")

    os.makedirs(os.path.dirname(BAK), exist_ok=True)
    if not os.path.exists(BAK):
        shutil.copy2(SRC, BAK)
        print("backup ->", os.path.relpath(BAK, ROOT))

    write_text(text, crlf)
    print("applied (crlf=%s)" % crlf)
    return 0


def revert():
    if not os.path.exists(BAK):
        print("no backup to restore")
        return 1
    shutil.copy2(BAK, SRC)
    print("reverted from", os.path.relpath(BAK, ROOT))
    return 0


def status():
    text, _ = read_text()
    print("applied        :", MARKER in text)
    print("old block left :", text.count(OLD))
    print("ep0write logged:", text.count(E2_NEW))
    return 0


if __name__ == "__main__":
    if "--revert" in sys.argv:
        sys.exit(revert())
    if "--status" in sys.argv:
        sys.exit(status())
    sys.exit(apply())

