  g_usbdev.driver = driver;

  /* Bind the class driver */

  ret = CLASS_BIND(driver, &g_usbdev.usbdev);
  if (ret)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_BINDFAILED),
               (uint16_t)-ret);
      g_usbdev.driver = NULL;
