  hwp_hpsys_cfg->USBCR |= HPSYS_CFG_USBCR_DP_EN;
  g_usbdev.hw->power |= USB_POWER_SOFTCONN;

  /* Enable IRQ */

  up_enable_irq(SF32LB52_IRQ_USB);

