# -*- coding: utf-8 -*-
"""
patch_dbg_epintin.py -- temporary diagnostics for the RNDIS interrupt-IN
notification path.

Symptom (from .workbuddy/serial_rndis.log):
  The host sends REMOTE_NDIS_INITIALIZE_MSG (SEND_ENCAPSULATED_COMMAND,
  type=21 req=00), the firmware logs CLASS_SETUP -> 0, and then the host
  only does CLEAR_FEATURE(0x81/0x02/0x83) and re-sends INITIALIZE.  It never
  issues GET_ENCAPSULATED_RESPONSE (type=a1 req=01), which means the 8-byte
  RESPONSE_AVAILABLE notification never reached it on EP3 (0x83).

What this patch prints, so we can tell which link is broken:
  * epcfg    -- did EP_CONFIGURE really register EP3, and did INTRTXE get
                its bit 3?
  * epwrite  -- the FIFO3 write for the notification (TXCSR before/after)
  * epsubmit -- which submit branch ran and what it returned
  * notify   -- rndis_send_encapsulated_response(): EP_SUBMIT return value
  * isr      -- ISR trace cap raised 60 -> 400 so late EP3 IRQs are not
                silently dropped

Usage:
    python patch_dbg_epintin.py            # apply
    python patch_dbg_epintin.py --status   # show state
    python patch_dbg_epintin.py --revert   # undo (from .pre_dbgx backups)
"""

import os
import shutil
import sys

ROOT = "D:/sicelcd"
VENDOR = os.path.join(ROOT, "vendor", "sifli", "chips", "sf32lb52",
                      "sf32lb_usbdev.c")
RNDIS = os.path.join(ROOT, "nuttx", "drivers", "usbdev", "rndis.c")

MARK = "USBDBGX"

# ---------------------------------------------------------------------------
# (path, marker, old, new).  `@M@` is replaced by MARK.  Every `old` must
# match exactly once.
# ---------------------------------------------------------------------------

A_ISRCAP = (
    VENDOR,
    MARK + "_ISRCAP",
    "  if (g_usbdbg_isrs < 60)\n",
    "  if (g_usbdbg_isrs < 400)  /* @M@_ISRCAP */\n",
)

B_EPCFG = (
    VENDOR,
    MARK + "_EPCFG",
    """      /* Enable RX interrupt for this endpoint */

      hw->intrrxe |= (1 << epno);
    }

  return OK;
}
""",
    """      /* Enable RX interrupt for this endpoint */

      hw->intrrxe |= (1 << epno);
    }

  /* @M@_EPCFG: confirm the endpoint really got configured, and that its
   * interrupt-enable bit landed in INTRTXE / INTRRXE.  If EP3 (the RNDIS
   * interrupt IN endpoint) never shows up here, usbclass_setconfig()'s
   * EP_CONFIGURE never reached the controller -- and then no notification
   * can ever be delivered.
   */

#if USBDBG
  _err("USBDBGX epcfg: ep%u %s maxp=%u idx=%02x txcsr=%04x rxcsr=%04x"
       " intrtxe=%04x intrrxe=%04x\\n",
       (unsigned)epno, isin ? "IN" : "OUT", (unsigned)maxpacket,
       (unsigned)hw->index, (unsigned)hw->csr0_txcsr,
       (unsigned)hw->rxcsr,
       (unsigned)hw->intrtxe, (unsigned)hw->intrrxe);
#endif

  return OK;
}
""",
)

C_EPWRITE_PRE = (
    VENDOR,
    MARK + "_EPWRITE",
    """  ret = bytesleft;

  /* Flush FIFO if not empty */
""",
    """  ret = bytesleft;

  /* @M@_EPWRITE: dump every non-EP0 IN write so the notification packet can
   * be told apart from descriptor/string traffic.
   */

#if USBDBG
  if (epphy != 0)
    {
      _err("USBDBGX epwrite: ep%u n=%u last=%d txcsr_pre=%04x\\n",
           (unsigned)epphy, (unsigned)nbytes, (int)last,
           (unsigned)hw->csr0_txcsr);
    }
#endif

  /* Flush FIFO if not empty */
""",
)

C_EPWRITE_POST = (
    VENDOR,
    MARK + "_EPWRITE2",
    """  hw->csr0_txcsr = (hw->csr0_txcsr & ~USB_TXCSR_P_WZC_BITS)
