     */

    int notifret = EP_SUBMIT(priv->epintin, priv->epintin_req);
    _err("USBDBGX notify: RESPONSE_AVAILABLE size=%u submit=%d\\n",
         (unsigned)size, notifret);
    (void)notifret;
  }

  return OK;
