""",
)

EDITS = [A_ISRCAP, B_EPCFG, C_EPWRITE_PRE, C_EPWRITE_POST, D_EPSUBMIT, E_NOTIFY]


def read(path):
    return open(path, "rb").read()


def conv(text, crlf):
    return text.replace("\n", "\r\n").encode() if crlf else text.encode()


def apply_(dry=False):
    data = {p: read(p) for p in (VENDOR, RNDIS)}
    crlf = {p: b"\r\n" in data[p] for p in data}
    changed = set()

    for path, marker, old, new in EDITS:
        new = new.replace("@M@", MARK)
        if marker.encode() in data[path]:
            print("  skip (already applied): %s" % marker)
            continue
        o = conv(old, crlf[path])
        n = conv(new, crlf[path])
        cnt = data[path].count(o)
        if cnt != 1:
            print("  !! %s: anchor matched %d times (need 1)" % (marker, cnt))
            return 1
        data[path] = data[path].replace(o, n)
        changed.add(path)
        print("  patched: %s" % marker)

    if dry:
        print("  (dry run -- nothing written)")
        return 0

    for path in changed:
        bak = path + ".pre_dbgx"
        if not os.path.exists(bak):
            shutil.copy2(path, bak)
            print("  backup -> %s" % os.path.basename(bak))
        open(path, "wb").write(data[path])
    print("  done.")
    return 0


def status():
    data = {p: read(p) for p in (VENDOR, RNDIS)}
    for path, marker, _, _ in EDITS:
        print("  %-30s %s" % (marker,
                              "APPLIED" if marker.encode() in data[path]
                              else "not applied"))
    return 0


def revert():
    n = 0
    for path in (VENDOR, RNDIS):
        bak = path + ".pre_dbgx"
        if os.path.exists(bak):
            shutil.copy2(bak, path)
            os.remove(bak)
            print("  reverted %s" % os.path.basename(path))
            n += 1
    if not n:
        print("  nothing to revert")
    return 0


if __name__ == "__main__":
    arg = sys.argv[1] if len(sys.argv) > 1 else ""
    print("== patch_dbg_epintin ==")
    if arg == "--status":
        sys.exit(status())
    if arg == "--revert":
        sys.exit(revert())
    sys.exit(apply_(dry=(arg == "--dry-run")))

