# -*- coding: utf-8 -*-
"""
Dump the Windows PnP state for every SF32LB52 USB instance (parent + interfaces).

`reg query` expands HKLM to HKEY_LOCAL_MACHINE, and pnputil emits GBK on a
Chinese Windows, so both are normalised here in one place.

Usage: python devdump.py [VIDPID]
       VIDPID defaults to 38F4
"""
import subprocess
import sys

VID = sys.argv[1] if len(sys.argv) > 1 else "38F4"
ENUM = r"HKLM\SYSTEM\CurrentControlSet\Enum\USB"


def sh(cmd):
    p = subprocess.run(cmd, shell=True, capture_output=True)
    raw = p.stdout + p.stderr
    for enc in ("gbk", "utf-8"):
        try:
            return raw.decode(enc).replace("\r", "").strip()
        except Exception:
            pass
    return raw.decode("latin-1", "ignore").replace("\r", "").strip()


def keys_under(path):
    out = sh('reg query "%s"' % path)
    got = []
    for line in out.splitlines():
        line = line.strip()
        if line.upper().startswith("HKEY_"):
            got.append(line)
    return got


def regvals(key, names):
    out = sh('reg query "%s"' % key)
    vals = {}
    for line in out.splitlines():
        parts = line.strip().split(None, 2)
        if len(parts) == 3 and parts[1].startswith("REG_"):
            vals[parts[0]] = parts[2]
    return {n: vals.get(n) for n in names}


def pnp_state(key):
    """pnputil needs the instance id, not a full registry key."""
    inst = key.split("Enum\\", 1)[-1]
    out = sh('pnputil /enum-devices /instanceid "%s" /drivers' % inst)
    keep = ("实例 ID", "设备描述", "类名", "制造商", "状态", "问题代码",
            "问题状态", "驱动程序名称", "匹配设备 ID", "驱动程序版本",
            "Instance ID", "Device Description", "Status", "Problem")
    return [ln.strip() for ln in out.splitlines()
            if any(k in ln for k in keep)]


def main():
    root = "%s\\VID_%s&PID_FFFF" % (ENUM, VID)
    print("=" * 70)
    print("registry under %s" % root)
    print("=" * 70)

    families = [root] + keys_under(root)
    # interface nodes live in sibling keys named ...&MI_xx
    for k in keys_under(ENUM):
        if "VID_%s" % VID in k and "MI_" in k:
            families.append(k)

    for fam in families:
        insts = [fam] if fam != root else keys_under(fam)
        for inst in insts:
            print("\n" + "-" * 70)
            print("### %s" % inst)
            print("  --- registry ---")
            v = regvals(inst, ("HardwareID", "CompatibleIDs", "Service",
                               "ConfigFlags", "ClassGUID", "DeviceDesc",
                               "Driver", "Capabilities"))
            for name in ("DeviceDesc", "Service", "ConfigFlags", "ClassGUID",
                         "Capabilities", "Driver"):
                if v.get(name):
                    print("     %-14s %s" % (name, v[name][-90:]))
            for name in ("HardwareID", "CompatibleIDs"):
                if v.get(name):
                    print("     %s:" % name)
                    for item in v[name].split("\\0"):
                        print("        %s" % item)
            print("  --- pnp ---")
            for ln in pnp_state(inst):
                print("     %s" % ln)


if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""
Find every USB device instance on this machine whose bound service or
description looks RNDIS-ish, and print its device-descriptor-derived
compatible IDs. Used as ground truth for how Windows derives the
class-based IDs for RNDIS devices.

Usage: python rndis_ground_truth.py
"""
import subprocess

ENUM = r"HKLM\SYSTEM\CurrentControlSet\Enum\USB"
SERVICES = ("usbrndis6", "usb80236", "wceisvista", "rndis", "usbccgp")
DESCS = ("NDIS", "RNDIS", "Internet Sharing", "Composite")


def sh(cmd):
    p = subprocess.run(cmd, shell=True, capture_output=True)
    raw = p.stdout + p.stderr
    for enc in ("gbk", "utf-8"):
        try:
            return raw.decode(enc).replace("\r", "").strip()
        except Exception:
            pass
    return raw.decode("latin-1", "ignore").replace("\r", "").strip()


def subkeys(path):
    out = sh('reg query "%s"' % path)
    return [l.strip() for l in out.splitlines() if l.strip().upper().startswith("HKEY_")]


def vals(key):
    out = sh('reg query "%s"' % key)
    d = {}
    for line in out.splitlines():
        p = line.strip().split(None, 2)
        if len(p) == 3 and p[1].startswith("REG_"):
            d[p[0]] = p[2]
    return d


def main():
    hits = []
    for fam in subkeys(ENUM):
        for inst in [fam] + subkeys(fam):
            v = vals(inst)
            svc = v.get("Service", "")
            desc = v.get("DeviceDesc", "")
            if any(s.lower() in svc.lower() for s in SERVICES) or \
               any(s.lower() in desc.lower() for s in DESCS):
                hits.append((inst, v))

    for inst, v in hits:
        print("=" * 74)
        print(inst)
        print("  Service      :", v.get("Service"))
        print("  DeviceDesc   :", v.get("DeviceDesc"))
        print("  ClassGUID    :", v.get("ClassGUID"))
        print("  HardwareID   :")
        for x in v.get("HardwareID", "").split("\\0"):
            if x:
                print("      ", x)
        print("  CompatibleIDs:")
        for x in v.get("CompatibleIDs", "").split("\\0"):
            if x:
                print("      ", x)

    print("\n%d instances" % len(hits))


if __name__ == "__main__":
    main()

