# -*- coding: utf-8 -*-
"""
Report the full Windows PnP tree for the SF32LB52 USB device, including the
usbccgp child interfaces (--&MI_00 / &MI_01--) that carry the RNDIS function.

`reg query` expands HKLM to HKEY_LOCAL_MACHINE and pnputil prints GBK on a
Chinese Windows, so both are normalised here.

Usage: python state.py
"""
import subprocess

ENUM = r"HKLM\SYSTEM\CurrentControlSet\Enum\USB"
NEED = ("DeviceDesc", "Service", "ConfigFlags", "ClassGUID", "Driver")


def sh(cmd):
    p = subprocess.run(cmd, shell=True, capture_output=True)
    raw = p.stdout + p.stderr
    for enc in ("gbk", "utf-8"):
        try:
            return raw.decode(enc).replace("\r", "").strip()
        except Exception:
            pass
    return raw.decode("latin-1", "ignore").replace("\r", "").strip()


def subkeys(path):
    return [l.strip() for l in sh('reg query "%s"' % path).splitlines()
            if l.strip().upper().startswith("HKEY_")]


def vals(key):
    d = {}
    for line in sh('reg query "%s"' % key).splitlines():
        p = line.strip().split(None, 2)
        if len(p) == 3 and p[1].startswith("REG_"):
            d[p[0]] = p[2]
    return d


def walk(path):
    """Yield instance keys: a key with a 'Service' value is a leaf instance."""
    for k in subkeys(path):
        v = vals(k)
        if "Service" in v or "DeviceDesc" in v:
            yield k, v
        else:
            for kk, vv in walk(k):
                yield kk, vv


def pnp(inst):
    inst = inst.split("Enum\\", 1)[-1]
    out = sh('pnputil /enum-devices /instanceid "%s" /drivers' % inst)
    keep = ("设备描述", "类名", "状态", "问题代码", "问题状态",
            "驱动程序名称", "匹配设备 ID", "驱动程序版本")
    return [l.strip() for l in out.splitlines() if any(k in l for k in keep)]


def main():
    fams = [k for k in subkeys(ENUM) if "VID_38F4" in k]
    for fam in fams:
        for inst, v in walk(fam):
            print("=" * 74)
            print(inst)
            desc = v.get("DeviceDesc", "")
            print("  DeviceDesc : %s" % desc.split(";")[-1])
            print("  Service    : %s" % v.get("Service"))
            print("  ConfigFlags: %s" % v.get("ConfigFlags"))
            for x in v.get("CompatibleIDs", "").split("\\0"):
                if x:
                    print("   CID: %s" % x)
            body = pnp(inst)
            if body:
                print("  --- pnp ---")
                for ln in body:
                    print("     %s" % ln)
            else:
                print("  --- pnp --- (not present)")


if __name__ == "__main__":
    main()

