657→    }
658→  else
659→    {
660→      bytesleft = hw->rxcount;
661→    }
662→
663→  if (bytesleft > nbytes)
664→    {
665→      bytesleft = nbytes;
666→    }
667→
668→  int ret = bytesleft;
669→
670→  /* Read data from FIFO using 32-bit access when possible */
671→
672→  if (((uintptr_t)buf & 0x03) == 0)
673→    {
674→      uint32_t *buf32 = (uint32_t *)buf;
675→      while (bytesleft >= 4)
