static void sf32lb52_epreset(struct sf32lb52_usbdev_s *priv,
                             unsigned int index)
{
  volatile USBC_X_Typedef *hw = priv->hw;
  volatile USBC_X_Typedef *regs = SF32LB52_EPREGS(hw, index);

  hw->index = index;
  if (index == 0)
    {
      regs->csr0_txcsr = USB_CSR0_FLUSHFIFO;
    }
  else
