      /* Flush TX FIFO */

      regs->csr0_txcsr = USB_TXCSR_FLUSHFIFO | USB_TXCSR_CLRDATATOG;

      /* Flush RX FIFO */

      regs->rxcsr = USB_RXCSR_FLUSHFIFO | USB_RXCSR_CLRDATATOG;
