  /* Select EP0 as default */

  hw->index = 0;

  /* USBDBGX_EPPROBE: does every endpoint's register page actually exist?
   *
   * MUSB reports the implemented endpoint count in EPINFO[3:0] (excluding
   * EP0; 0 means 16).  Writing a known pattern into each endpoint's TXMAXP
   * and reading it back tells us whether that endpoint is real -- a page for
   * a non-existent endpoint reads back as zero and swallows writes.  This is
   * the difference between "EP3 is dead" and "the RNDIS notification is
   * dropped somewhere else".
   */

#if USBDBG
  _err("USBDBGX epprobe: epinfo=%02x n_ep_excl_ep0=%u raminfo=%02x"
       " linkinfo=%02x hwvers=%04x\n",
       (unsigned)hw->epinfo, (unsigned)(hw->epinfo & 0x0f),
       (unsigned)hw->raminfo, (unsigned)hw->linkinfo,
       (unsigned)hw->hwvers);

  for (i = 1; i < SF32LB52_NENDPOINTS; i++)
    {
      volatile USBC_X_Typedef *regs = SF32LB52_EPREGS(hw, i);
      uint16_t saved = regs->txmaxp;

      regs->txmaxp = 0x1234;

      _err("USBDBGX epprobe: ep%u page_txmaxp saved=%04x readback=%04x"
           " idx_win_txmaxp=%04x\n",
           (unsigned)i, (unsigned)saved, (unsigned)regs->txmaxp,
           (unsigned)((hw->index = i, hw->txmaxp)));

      regs->txmaxp = saved;
    }

  hw->index = 0;
#endif
}

