/****************************************************************************
 * apps/examples/usb_tput/usb_tput_main.c
 *
 * USB throughput test for the SF32LB52 CDC/ACM (or any) character device.
 *
 * The point of this app is to answer a question with a number instead of an
 * opinion: the SF32LB52's USB PHY is Full-Speed only (measured -- HSENAB set,
 * POWER.HSMODE never asserted), so 12 Mbps / ~1 MB/s is a hard ceiling shared
 * by every USB class on this part.  This measures where we actually land
 * relative to that ceiling.
 *
 * Usage:
 *   usbtput tx   [seconds] [devpath]   device -> host, write as fast as possible
 *   usbtput rx   [seconds] [devpath]   host -> device, read and discard
 *   usbtput echo [seconds] [devpath]   host -> device -> host, read then write back
 *
 * Defaults: 10 seconds, /dev/ttyACM0.
 *
 * Notes:
 *   - tx needs a reader on the host or the CDC/ACM TX queue simply fills and
 *     the write blocks, which is reported rather than hidden.
 *   - echo is the useful one for a round-trip test: drive it from the host by
 *     writing a known byte count and reading the same back.
 *
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#include <nuttx/clock.h>

#define TP_BUF_SIZE 4096

static uint8_t g_buffer[TP_BUF_SIZE];

/****************************************************************************
 * Name: elapsed_us
 *
 * Description:
 *   Microseconds elapsed since 'start' (a clock_systime_ticks() stamp).
 *   Ticks are converted via TICK_PER_SEC so this works at any tick rate.
 *
 ****************************************************************************/

static unsigned long elapsed_us(clock_t start)
{
  clock_t ticks = clock_systime_ticks() - start;

  return (unsigned long)((uint64_t)ticks * 1000000ull / TICK_PER_SEC);
}

/****************************************************************************
 * Name: report
 ****************************************************************************/

static void report(const char *what, unsigned long bytes, unsigned long us)
{
  unsigned long kb_per_s;

  if (us == 0)
    {
      us = 1;
    }

  /* bytes * 1000000 / us / 1024, kept in integer maths but scaled first so
   * the result does not collapse to 0 on a fast run.
   */

  kb_per_s = (unsigned long)(((uint64_t)bytes * 1000000ull) / us / 1024ull);

  printf("usbtput %s: %lu bytes in %lu us = %lu KB/s (%lu.%02lu MB/s)\n",
         what, bytes, us, kb_per_s, kb_per_s / 1024, (kb_per_s % 1024) * 100 / 1024);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  const char *mode    = (argc > 1) ? argv[1] : "tx";
  int         seconds = (argc > 2) ? atoi(argv[2]) : 10;
  const char *path    = (argc > 3) ? argv[3] : CONFIG_EXAMPLES_USB_TPUT_DEVPATH;
  int         oflags;
  unsigned long total = 0;
  clock_t     start;
  int         fd;
  int         i;

  if (seconds <= 0)
    {
      seconds = 10;
    }

  if (strcmp(mode, "tx") == 0)
    {
      oflags = O_WRONLY;
    }
  else if (strcmp(mode, "rx") == 0)
    {
      oflags = O_RDONLY;
    }
  else if (strcmp(mode, "echo") == 0)
    {
