    }

  fd = open(path, oflags);
  if (fd < 0)
    {
      printf("usbtput: open(%s) failed: %d\n", path, errno);
      return 1;
    }

  printf("usbtput: %s on %s for %d s (placeholder; see console notes)\n",
         mode, path, seconds);

  start = clock_systime_ticks();

  for (;;)
    {
      unsigned long us = elapsed_us(start);

      if (us >= (unsigned long)seconds * 1000000ul)
        {
          break;
        }

      if (strcmp(mode, "tx") == 0)
        {
          ssize_t n = write(fd, g_buffer, TP_BUF_SIZE);
          if (n <= 0)
            {
              printf("usbtput: write failed: %d (after %lu bytes)\n",
                     (int)n, total);
              break;
            }

          total += (unsigned long)n;
        }
      else
        {
          ssize_t n = read(fd, g_buffer, TP_BUF_SIZE);
          if (n < 0)
            {
              printf("usbtput: read failed: %d (after %lu bytes)\n",
                     errno, total);
              break;
            }

          total += (unsigned long)n;

          if (strcmp(mode, "echo") == 0 && n > 0)
            {
              ssize_t w = write(fd, g_buffer, (size_t)n);
              if (w <= 0)
                {
                  printf("usbtput: echo write failed: %d\n", (int)w);
                  break;
                }
            }
        }
    }

  report(mode, total, elapsed_us(start));
  close(fd);
  return 0;
}

