void wc_link_poll(wc_frame_cb_t cb, void *arg)
{
  uint8_t chunk[256];
  ssize_t n;
  int     budget = 16;

  if (g_fd < 0)
    {
      return;
    }

  /* 一次最多读 4KB，避免长时间占用主循环 */

  while (budget-- > 0)
    {
      n = read(g_fd, chunk, sizeof(chunk));
      if (n <= 0)
        {
          break;
        }

      wc_parser_push(&g_parser, chunk, (size_t)n);

      while (wc_parser_next(&g_parser, &g_frame_scratch))
        {
          if (cb)
            {
              cb(&g_frame_scratch, arg);
            }
        }
    }
}

