{
  uint8_t chunk[256];
  ssize_t n;

  if (g_fd < 0)
    {
      return;
    }

  /* 一次最多处理 4KB，避免长时间占用主循环 */

  int budget = 16;
  while (budget-- > 0)
    {
      n = read(g_fd, chunk, sizeof(chunk));
      if (n <= 0)
        {
          break;
        }

      size_t off = 0;
      while (off < (size_t)n)
        {
          struct wc_frame_s f;

          if (wc_parser_feed(&g_parser, chunk + off, (size_t)n - off, &f))
            {
              off = (size_t)n;      /* 解析器已消费到帧尾附近，剩余下一轮再喂 */
              if (cb)
                {
                  cb(&f, arg);
                }
              break;
            }
          else
            {
              break;                /* 需要更多数据 */
            }
        }
    }
}

