#!/usr/bin/env python3
"""USB 端口恢复: 重启失败节点 / 根集线器, 等待板端 CDC 端口出现。"""
import subprocess
import sys
import time


def sh(cmd):
    p = subprocess.run(cmd, shell=True, capture_output=True)
    raw = p.stdout + p.stderr
    for enc in ("utf-16le", "utf-8", "gbk"):
        try:
            return raw.decode(enc).replace("\r", "")
        except Exception:
            pass
    return raw.decode("latin-1", "ignore")


def ports_38f4():
    from serial.tools import list_ports
    return [p.device for p in list_ports.comports()
            if "38F4" in (p.hwid or "").upper()]


def wait_port(secs=20):
    for _ in range(int(secs / 2)):
        time.sleep(2)
        got = ports_38f4()
        if got:
            return got[0]
    return None


def main():
    # 1) 重启描述符失败的节点 (强制端口复位, 重新要描述符)
    bad = sh('pnputil /enum-devices /problem')
    for b in bad.split("\n\n"):
        if "VID_0000&PID_0002" in b:
            import re
            m = re.search(r"实例 ID:\s*(\S+)", b)
            if m:
                inst = m.group(1)
                print("[1] restart:", inst)
                print(sh('pnputil /restart-device "%s"' % inst).strip()[:200])

    p = wait_port(16)
    if p:
        print("[OK] port:", p)
        return 0

    # 2) 重启根集线器
    hubs = sh("pnputil /enum-devices /class USB")
    for b in hubs.split("\n\n"):
        if "ROOT_HUB" in b and "已启动" in b:
            import re
            m = re.search(r"实例 ID:\s*(\S+)", b)
            if m:
                inst = m.group(1)
                print("[2] restart hub:", inst)
                out = sh('pnputil /restart-device "%s"' % inst)
                print(out.strip().replace("\n", " | ")[:160])
                p = wait_port(16)
                if p:
                    print("[OK] port:", p)
                    return 0

    print("[FAIL] no CDC port")
    return 1


if __name__ == "__main__":
    sys.exit(main())

