/****************************************************************************
 * app/wristclaw/wc_ui.h
 *
 * 腕灵犀手表 UI（LVGL，390x450 AMOLED + FT6146 触摸）
 *
 * 与 Agent 同任务运行（主循环里调 wc_ui_tick），共享状态无需加锁。
 * 三页 tileview，触摸左右滑动切换：
 *   页0 表盘：时间/日期 + 状态行 + 链路状态
 *   页1 对话：Agent 最近输出（滚动）
 *   页2 提醒：待触发提醒列表
 ****************************************************************************/

#ifndef __APP_WRISTCLAW_WC_UI_H
#define __APP_WRISTCLAW_WC_UI_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdbool.h>
#include <stddef.h>

#ifdef CONFIG_GRAPHICS_LVGL

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct wc_ui_info_s
{
  bool link;                        /* 上位机链路状态 */
  int  nrem;                        /* 待触发提醒数 */
  int  nmemo;                       /* 备忘条数 */
  int  nskill;                      /* 已加载 Skill 数 */
  int  bright;                      /* 亮度百分比 */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* 初始化 LVGL 与显示/触摸。失败（如无 fb）时内部置 ui_ok=false，
 * 后续 tick/say 全部空操作，Agent 照常无头运行。 */

void wc_ui_init(void);

/* 主循环调用：驱动 LVGL 定时器 */

void wc_ui_tick(void);

/* Agent 输出一行（say 的所有去向之一，同任务调用安全） */

void wc_ui_say(const char *line);

/* 周期性喂状态快照（主循环 1Hz 调一次即可） */

void wc_ui_status(const struct wc_ui_info_s *info);

/* 待触发提醒文本列表（行格式 "mm:ss 文本"，n<=8） */

void wc_ui_reminders(char items[][48], int n);

#endif /* CONFIG_GRAPHICS_LVGL */
#endif /* __APP_WRISTCLAW_WC_UI_H */

/****************************************************************************
 * app/wristclaw/wc_ui.c
 *
 * LVGL 9.2 UI：3 页 tileview（表盘 / 对话 / 提醒），中文用内置
 * lv_font_simsun_16_cjk（常见字子集，个别生僻字会留空 —— 文案尽量用常用字）。
 *
 * 与 Agent 同任务：wc_ui_tick() 由主循环 20ms 调一次，内部驱动
 * lv_timer_handler()；所有数据更新都发生在 LVGL 线程，无需加锁。
 ****************************************************************************/

