/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define UI_CHAT_LINES   8
#define UI_CHAT_MAXLEN  96

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool g_ui_ok;
