/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* CJK 字体；无该字体时回落默认 */

static const lv_font_t *cjk_font(void)
{
#ifdef CONFIG_LV_FONT_SIMSUN_16_CJK
  return &lv_font_simsun_16_cjk;
#else
  return NULL;
#endif
}

static lv_obj_t *new_label(lv_obj_t *parent, const lv_font_t *font,
                           lv_color_t color)
{
  lv_obj_t *lbl = lv_label_create(parent);

  lv_obj_set_width(lbl, LV_PCT(92));
  lv_label_set_long_mode(lbl, LV_LABEL_LONG_WRAP);
  if (font != NULL)
    {
      lv_obj_set_style_text_font(lbl, font, 0);
    }
  lv_obj_set_style_text_color(lbl, color, 0);
  return lbl;
}

/* 1Hz：刷新表盘时钟 / 状态行 / 链路点 */

static void ui_timer_cb(lv_timer_t *timer)
{
  struct tm tm_now;
  time_t now;
  char buf[64];
  const lv_font_t *font = cjk_font();

  now = time(NULL);
  localtime_r(&now, &tm_now);

  snprintf(buf, sizeof(buf), "%02d:%02d", tm_now.tm_hour, tm_now.tm_min);
  lv_label_set_text(g_lbl_time, buf);

  snprintf(buf, sizeof(buf), "%d月%d日 星期%d",
           tm_now.tm_mon + 1, tm_now.tm_mday, tm_now.tm_wday);
  lv_label_set_text(g_lbl_date, buf);

  snprintf(buf, sizeof(buf),
