static void link_tick(void)
{
  static int  g_open_fail;
  uint32_t t = now_ms();

  if (!g_link_up)
    {
      int ret;

      if (t - g_last_link_try < WC_LINK_RETRY_MS)
        {
          return;
        }

      g_last_link_try = t;
      ret = wc_link_open(WC_LINK_PATH);
      if (ret == 0)
        {
          g_open_fail = 0;
          g_link_up = true;
          syslog(LOG_INFO, "WristClaw: link up on %s\n", WC_LINK_PATH);
          wc_agent_on_link_up();
        }
      else if (-ret == 107 /* ENOTCONN */ &&
               ++g_open_fail >= WC_SOFTCONN_AFTER)
        {
          /* 主机侧端口卡在旧的失败会话里：拉掉/拉起 D+ 上拉，
           * 制造一次主机可见的断开/连接 */

          g_open_fail = 0;
          syslog(LOG_WARNING,
                 "WristClaw: USB stuck, toggling SOFTCONN to re-attach\n");
          WC_USBC_POWER &= ~WC_USB_SOFTCONN;
          usleep(1000000);
          WC_USBC_POWER |= WC_USB_SOFTCONN;
        }
      return;
    }

