  for (i = 0; i < g_nmemos; i++)
    {
      snprintf(lines[i], WC_TEXT_LEN, "%s", g_memos[i]);
      ptrs[i] = lines[i];
    }

  (void)file_save_lines(path, ptrs, g_nmemos);
}

