  g_lbl_memo = mk_label(tile, "暂无", cjk(), dim, 340);
  lv_obj_align(g_lbl_memo, LV_ALIGN_TOP_LEFT, 16, 272);

  lv_timer_create(ui_timer_cb, 1000, NULL);
  ui_timer_cb(NULL);

  g_ui_ok = true;
