/* 画一根表针：角度 0° = 12 点方向，顺时针 */

static void draw_hand(lv_layer_t *layer, int cx, int cy, int len,
                      int deg, int width, uint32_t color)
{
  lv_draw_line_dsc_t dsc;
  float              rad = (float)(deg - 90) * 3.14159265f / 180.0f;

  lv_draw_line_dsc_init(&dsc);
  dsc.color       = lv_color_hex(color);
  dsc.width       = width;
  dsc.round_start = 1;
  dsc.round_end   = 1;
  dsc.p1.x        = cx;
  dsc.p1.y        = cy;
  dsc.p2.x        = cx + (int)((float)len * cosf(rad));
  dsc.p2.y        = cy + (int)((float)len * sinf(rad));
  lv_draw_line(layer, &dsc);
}

/* 表盘自绘事件：三根表针 + 中心点 */

static void face_draw_cb(lv_event_t *e)
{
  lv_obj_t   *obj   = lv_event_get_target(e);
  lv_layer_t *layer = lv_event_get_layer(e);
  lv_area_t   area;
  lv_draw_rect_dsc_t rdsc;
  lv_area_t   dot;
  int         cx;
  int         cy;
  int         r;
  int         deg_h;
  int         deg_m;
  int         deg_s;

  lv_obj_get_coords(obj, &area);
  cx = (area.x1 + area.x2) / 2;
  cy = (area.y1 + area.y2) / 2;
  r  = (area.x2 - area.x1) / 2 - 24;

  deg_s = g_ss * 6;
  deg_m = g_mm * 6 + g_ss / 10;
  deg_h = (g_hh % 12) * 30 + g_mm / 2;

  draw_hand(layer, cx, cy, r * 55 / 100, deg_h, 6, C_TEXT);
  draw_hand(layer, cx, cy, r * 78 / 100, deg_m, 4, C_TEXT);
  draw_hand(layer, cx, cy, r * 88 / 100, deg_s, 2, C_ACCENT);

  lv_draw_rect_dsc_init(&rdsc);
  rdsc.bg_color = lv_color_hex(C_ACCENT);
  rdsc.bg_opa   = LV_OPA_COVER;
  rdsc.radius   = LV_RADIUS_CIRCLE;
  dot.x1 = cx - 4;
  dot.y1 = cy - 4;
  dot.x2 = cx + 4;
  dot.y2 = cy + 4;
  lv_draw_rect(layer, &rdsc, &dot);
}

