/* 表盘自绘事件：60 条分刻度 + 12 条时刻度 + 三根表针 + 中心点
 * （完全自绘，不依赖 lv_scale；所有坐标都在同一次绘制内算出，
 *   避免「表针与刻度不同层」造成的错位） */

static void face_draw_cb(lv_event_t *e)
{
  lv_obj_t   *obj   = lv_event_get_target(e);
  lv_layer_t *layer = lv_event_get_layer(e);
  lv_area_t   area;
  lv_draw_line_dsc_t ldsc;
  lv_draw_rect_dsc_t rdsc;
  lv_area_t   dot;
  int         cx;
  int         cy;
  int         r;
  int         i;

  lv_obj_get_coords(obj, &area);
  cx = (area.x1 + area.x2) / 2;
  cy = (area.y1 + area.y2) / 2;
  r  = (area.x2 - area.x1) / 2 - 10;

  /* ---- 刻度：60 分钟刻度，每 5 条加长加亮 ---- */

  for (i = 0; i < 60; i++)
    {
      float rad = (float)(i * 6 - 90) * 3.14159265f / 180.0f;
      int   is_hour = (i % 5) == 0;
      int   len  = is_hour ? 12 : 5;
      float cosr = cosf(rad);
      float sinr = sinf(rad);

      lv_draw_line_dsc_init(&ldsc);
      ldsc.color = lv_color_hex(is_hour ? 0xD0D0D0 : 0x585858);
      ldsc.width = is_hour ? 3 : 1;
      ldsc.p1.x  = cx + (int)((float)(r - len) * cosr);
      ldsc.p1.y  = cy + (int)((float)(r - len) * sinr);
      ldsc.p2.x  = cx + (int)((float)r * cosr);
      ldsc.p2.y  = cy + (int)((float)r * sinr);
      lv_draw_line(layer, &ldsc);
    }

  /* ---- 表针 ---- */

  draw_hand(layer, cx, cy, r * 52 / 100, g_hh % 12 * 30 + g_mm / 2, 7, C_TEXT);
  draw_hand(layer, cx, cy, r * 76 / 100, g_mm * 6 + g_ss / 10, 5, C_TEXT);
  draw_hand(layer, cx, cy, r * 86 / 100, g_ss * 6, 2, C_ACCENT);

  /* ---- 中心点 ---- */

  lv_draw_rect_dsc_init(&rdsc);
  rdsc.bg_color = lv_color_hex(C_ACCENT);
  rdsc.bg_opa   = LV_OPA_COVER;
  rdsc.radius   = LV_RADIUS_CIRCLE;
  dot.x1 = cx - 5;
  dot.y1 = cy - 5;
  dot.x2 = cx + 5;
  dot.y2 = cy + 5;
  lv_draw_rect(layer, &rdsc, &dot);
}

