/* LVGL 的 LV_SYMBOL_* 图标位于私用区（PUA），黑体里没有对应字形，
 * 用内置 Montserrat 作为后备字体补齐；中文仍走 wc_font_16。 */

wc_font_16.fallback = &lv_font_montserrat_16;
